function sweepBall(brick, x0, y0, x1, y1, r) {
  const minX = brick.x - r, maxX = brick.x + brick.w + r;
  const minY = brick.y - r, maxY = brick.y + brick.h + r;
  const dx = x1 - x0, dy = y1 - y0;

  let tInX = -Infinity, tOutX = Infinity;
  if (Math.abs(dx) < EPS) {
    if (x0 <= minX || x0 >= maxX) return null;
  } else {
    tInX = (minX - x0) / dx;
    tOutX = (maxX - x0) / dx;
    if (tInX > tOutX) [tInX, tOutX] = [tOutX, tInX];
  }
  let tInY = -Infinity, tOutY = Infinity;
  if (Math.abs(dy) < EPS) {
    if (y0 <= minY || y0 >= maxY) return null;
  } else {
    tInY = (minY - y0) / dy;
    tOutY = (maxY - y0) / dy;
    if (tInY > tOutY) [tInY, tOutY] = [tOutY, tInY];
  }

  const tIn = Math.max(tInX, tInY);
  const tOut = Math.min(tOutX, tOutY);
  if (tIn > tOut || tOut <= 0 || tIn > 1) return null;

  let face;
  if (tInX > tInY + EPS) face = 'x';
  else if (tInY > tInX + EPS) face = 'y';
  else face = 'corner';

  return { t: Math.max(0, tIn), face, inside: tIn < 0 };
}
```

