export function bounceBricks(state) {
  const { ball, bricks } = state;
  const px = ball.px ?? ball.x;
  const py = ball.py ?? ball.y;

  let best = null, bestT = Infinity, bestHit = null;
  for (const brick of bricks) {
    if (!brick.alive) continue;
    const hit = sweepBall(brick, px, py, ball.x, ball.y, ball.r);
    if (hit && hit.t < bestT) { best = brick; bestT = hit.t; bestHit = hit; }
  }
  if (!best) return false;

  resolveBounce(ball, best, bestHit);
  best.alive = false;
  state.combo += 1;
  state.score += scoreForBrick(best, state.combo);
  return true;
}
```

