// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls and the paddle. Does NOT handle bricks: bounceBricks() sweeps the
// ball against the bricks after the move, using the previous position recorded
// here. Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;

  // Previous position, for the swept brick collision (bounceBricks) and for
  // the paddle crossing test below.
  ball.px = ball.x;
  ball.py = ball.y;

  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

  // Side walls
  if (ball.x - ball.r < 0) {
    ball.x = ball.r;
    ball.vx = Math.abs(ball.vx);
  } else if (ball.x + ball.r > WIDTH) {
    ball.x = WIDTH - ball.r;
    ball.vx = -Math.abs(ball.vx);
  }

  // Ceiling
  if (ball.y - ball.r < 0) {
    ball.y = ball.r;
    ball.vy = Math.abs(ball.vy);
  }

  // Paddle. The ball is caught when its bottom edge CROSSES the paddle's top
  // plane this frame, or when it already overlaps the paddle (the paddle
  // teleports with the mouse and can move under a falling ball). A simple
  // "bottom edge inside the 12px band" test lets the ball through whenever the
  // step is longer than the band. The ball always leaves through the top.
  const prevBottom = ball.py + ball.r;
  const xOverlap = ball.x + ball.r > paddle.x && ball.x - ball.r < paddle.x + paddle.w;
  const crossesTop = prevBottom <= paddle.y && ball.y + ball.r >= paddle.y;
  const overlapsPaddle = ball.y + ball.r >= paddle.y && ball.y - ball.r <= paddle.y + paddle.h;
  if (ball.vy > 0 && xOverlap && (crossesTop || overlapsPaddle)) {
    ball.y = paddle.y - ball.r;
    // The rebound angle depends on where the paddle was hit.
    const hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
    ball.vx = ballSpeed(state.level) * 0.6 * hit;
    // Renormalize: the rebound speed is the level speed whatever the entry
    // speed, so the ball neither accelerates nor slows down over rallies.
    ball.vy = -Math.sqrt(ballSpeed(state.level) ** 2 - ball.vx ** 2);
    state.combo = 0; // touching the paddle resets the combo
  }

