content.text:
// --- Collision (tested primitives) -----------------------------------------

// True if the ball (circle approximated by its box) overlaps the brick.
// Simple AABB test: it only says WHETHER the ball and the brick overlap at a
// single instant, not WHICH face was hit. Discrete and instant-only: it cannot
// see a brick crossed entirely between two frames (tunneling), so the real
// bounce below sweeps the segment between the previous and current positions.
export function collides(ball, brick) {
  return (
    ball.x + ball.r > brick.x &&
    ball.x - ball.r < brick.x + brick.w &&
    ball.y + ball.r > brick.y &&
    ball.y - ball.r < brick.y + brick.h
  );
}

// Slab method for a swept AABB: sweeps the ball (a box inflated by its radius)
// along the segment (x0,y0) -> (x1,y1) against `brick`. Returns the entry time
// `t` (0..1), the face crossed at entry, and whether the sweep STARTED inside
// the box (defensive — unreachable once every bounce pushes the ball out).
// The face is the slab entered LAST: that is the plane the ball actually
// crossed into the box. Equal entry times = the corner (both axes at once).
const EPS = 1e-9;

function sweepBall(brick, x0, y0, x1, y1, r) {
  const minX = brick.x - r;
  const maxX = brick.x + brick.w + r;
  const minY = brick.y - r;
  const maxY = brick.y + brick.h + r;
  const dx = x1 - x0;
  const dy = y1 - y0;

  let tInX = -Infinity;
  let tOutX = Infinity;
  if (Math.abs(dx) < EPS) {
    if (x0 <= minX || x0 >= maxX) return null; // parallel, outside the slab
  } else {
    tInX = (minX - x0) / dx;
    tOutX = (maxX - x0) / dx;
    if (tInX > tOutX) [tInX, tOutX] = [tOutX, tInX];
  }
  let tInY = -Infinity;
  let tOutY = Infinity;
  if (Math.abs(dy) < EPS) {
    if (y0 <= minY || y0 >= maxY) return null;
  } else {
    tInY = (minY - y0) / dy;
    tOutY = (maxY - y0) / dy;
    if (tInY > tOutY) [tInY, tOutY] = [tOutY, tInY];
  }

  const tIn = Math.max(tInX, tInY);
  const tOut = Math.min(tOutX, tOutY);
  // Miss: never inside the box on the segment, box fully behind, or box
  // beyond the end of the segment. `tOut <= 0` also rejects the degenerate
  // tangent-at-start case (ball pushed out last frame, moving away).
  if (tIn > tOut || tOut <= 0 || tIn > 1) return null;

  let face;
  // The slab entered LAST is the plane the ball crossed into the box.
  if (tInX > tInY + EPS) face = dx > 0 ? 'left' : 'right';
  else if (tInY > tInX + EPS) face = dy > 0 ? 'top' : 'bottom';
  else face = 'corner';
  return { t: Math.max(0, tIn), face, inside: tIn < 0 };
}

// Pushes the ball out of the brick and flips the velocity along the face hit.
// Y grows downward: the TOP face is the min-Y plane (ball above, vy > 0 on
// approach -> bounce to vy < 0), the BOTTOM face the max-Y plane, etc.
function resolveBounce(ball, brick, hit) {
  const t = hit.t;
  if (hit.inside) {
    // Defensive: the ball started the sweep already inside the box. Resolve by
    // minimum penetration at the current position; the invariant (ball always
    // pushed out after a bounce) means this is unreachable in play.
    if (!collides(ball, brick)) return;
    const penLeft = ball.x + ball.r - brick.x;
    const penRight = brick.x + brick.w - (ball.x - ball.r);
    const penTop = ball.y + ball.r - brick.y;
    const penBottom = brick.y + brick.h - (ball.y - ball.r);
    const penX = Math.min(penLeft, penRight);
    const penY = Math.min(penTop, penBottom);
    if (Math.abs(penX - penY) < EPS) {
      // Corner: both axes, place at the approach corner, flip both.
      ball.x = ball.vx >= 0 ? brick.x - ball.r : brick.x + brick.w + ball.r;
      ball.y = ball.vy >= 0 ? brick.y - ball.r : brick.y + brick.h + ball.r;
      ball.vx = -ball.vx;
      ball.vy = -ball.vy;
    } else if (penX < penY) {
      if (ball.vx > 0) {
        ball.x = brick.x - ball.r;
        ball.vx = -Math.abs(ball.vx);
      } else {
        ball.x = brick.x + brick.w + ball.r;
        ball.vx = Math.abs(ball.vx);
      }
    } else if (ball.vy > 0) {
      ball.y = brick.y - ball.r;
      ball.vy = -Math.abs(ball.vy);
    } else {
      ball.y = brick.y + brick.h + ball.r;
      ball.vy = Math.abs(ball.vy);
    }
    return;
  }

  const cx = ball.px + (ball.x - ball.px) * t;
  const cy = ball.py + (ball.y - ball.py) * t;
  switch (hit.face) {
    case 'top':
      ball.y = brick.y - ball.r;
      ball.x = cx;
      ball.vy = -Math.abs(ball.vy);
      break;
    case 'bottom':
      ball.y = brick.y + brick.h + ball.r;
      ball.x = cx;
      ball.vy = Math.abs(ball.vy);
      break;
    case 'left':
      ball.x = brick.x - ball.r;
      ball.y = cy;
      ball.vx = -Math.abs(ball.vx);
      break;
    case 'right':
      ball.x = brick.x + brick.w + ball.r;
      ball.y = cy;
      ball.vx = Math.abs(ball.vx);
      break;
    case 'corner':
      ball.x = cx;
      ball.y = cy;
      ball.vx = -ball.vx;
      ball.vy = -ball.vy;
      break;
  }
}

// Swept brick collision: sweeps the ball's motion segment against every live
// brick, resolves the FIRST contact (one bounce per pass, one brick per pass),
// kills that brick and scores it. Pure logic, no DOM.
// Returns true if a brick was hit.
export function bounceBricks(state) {
  const { ball, bricks } = state;
  const px = ball.px ?? ball.x;
  const py = ball.py ?? ball.y;

  let best = null;
  let bestT = Infinity;
  let bestHit = null;
  for (const brick of bricks) {
    if (!brick.alive) continue;
    const hit = sweepBall(brick, px, py, ball.x, ball.y, ball.r);
    if (hit && hit.t < bestT) {
      best = brick;
      bestT = hit.t;
      bestHit = hit;
    }
  }
  if (!best) return false;

  resolveBounce(ball, best, bestHit);
  best.alive = false;
  state.combo += 1;
  state.score += scoreForBrick(best, state.combo);
  return true;
}


// --- Score & combo (NOT covered by tests — debt #5) ------------------------

// Combo multiplier. UNBOUNDED today: a long combo makes the score blow up
// uncontrollably (see #5, expected improvement = clamp it).
export function comboMultiplier(combo) {
  return 1 + combo * 0.5;
}

// Points earned for breaking a brick, combo included.
export function scoreForBrick(brick, combo) {
  return Math.round(brick.points * comboMultiplier(combo));

