// --- Best score persistence ------------------------------------------------

// Reads the best score from a localStorage-compatible storage.
// Robust to corrupted or missing storage: returns 0 instead of throwing.
export function loadBest(storage) {
  if (!storage) return 0;
  try {
    const raw = storage.getItem(STORAGE_KEY);
    const value = Number.parseInt(raw, 10);
    return Number.isFinite(value) && value > 0 ? value : 0;
  } catch {
    return 0;
  }
}

// Writes the best score if the current score beats it. Returns the updated best.
export function saveBest(storage, score) {
  const best = loadBest(storage);
  if (score > best && storage) {
    try {
      storage.setItem(STORAGE_KEY, String(score));
    } catch {
      // storage unavailable (private mode, quota): silently ignore
    }
    return score;
  }
  return best;
}

// --- Physics (movement + wall/paddle bounces) ------------------------------

// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls and the paddle. Does NOT handle bricks: bounceBricks() sweeps the
// ball against the bricks after the move, using the previous position recorded
// here. Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;

  // Previous position, for the swept brick collision (bounceBricks) and for
  // the paddle crossing test below.
  ball.px = ball.x;
  ball.py = ball.y;

  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

  // Side walls
  if (ball.x - ball.r < 0) {
    ball.x = ball.r;
    ball.vx = Math.abs(ball.vx);
  } else if (ball.x + ball.r > WIDTH) {
    ball.x = WIDTH - ball.r;
    ball.vx = -Math.abs(ball.vx);
  }

  // Ceiling
  if (ball.y - ball.r < 0) {
    ball.y = ball.r;
    ball.vy = Math.abs(ball.vy);
  }

  // Paddle. The ball is caught when its bottom edge CROSSES the paddle's top
  // plane this frame, or when it already overlaps the paddle (the paddle
  // teleports with the mouse and can move under a falling ball). A simple
  // "bottom edge inside the 12px band" test lets the ball through whenever the
  // step is longer than the band. The ball always leaves through the top.
  const prevBottom = ball.py + ball.r;
  const xOverlap = ball.x + ball.r > paddle.x && ball.x - ball.r < paddle.x + paddle.w;
  const crossesTop = prevBottom <= paddle.y && ball.y + ball.r >= paddle.y;
  const overlapsPaddle = ball.y + ball.r >= paddle.y && ball.y - ball.r <= paddle.y + paddle.h;
  if (ball.vy > 0 && xOverlap && (crossesTop || overlapsPaddle)) {
    ball.y = paddle.y - ball.r;
    // The rebound angle depends on where the paddle was hit.
    const hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
    ball.vx = ballSpeed(state.level) * 0.6 * hit;
    // Renormalize: the rebound speed is the level speed whatever the entry
    // speed, so the ball neither accelerates nor slows down over rallies.
    ball.vy = -Math.sqrt(ballSpeed(state.level) ** 2 - ball.vx ** 2);
    state.combo = 0; // touching the paddle resets the combo
  }

  // Exit through the bottom: ball lost
  if (ball.y - ball.r > HEIGHT) {
    return true;
  }
  return false;
}

// --- Rendering (DOM) -------------------------------------------------------

// Main render loop. Bricks are drawn here; the bounce itself is pure logic in
// bounceBricks(), called from the game loop before drawing.
export function frame(ctx, state) {
  // Background
  ctx.fillStyle = palette.background;
  ctx.fillRect(0, 0, WIDTH, HEIGHT);

  // Bricks: drawing only.
  for (const brick of state.bricks) {
    if (!brick.alive) continue;
    ctx.fillStyle = brickColor(brick.row);
    ctx.fillRect(brick.x, brick.y, brick.w, brick.h);
  }

  // Paddle — color hard-coded instead of using the palette (inconsistency #6).
  ctx.fillStyle = '#00e5ff';
  ctx.fillRect(state.paddle.x, state.paddle.y, state.paddle.w, state.paddle.h);

  // Ball — also hard-coded (#6).
  ctx.fillStyle = '#39ff14';
  ctx.beginPath();
  ctx.arc(state.ball.x, state.ball.y, state.ball.r, 0, Math.PI * 2);
  ctx.fill();

  // HUD
  ctx.fillStyle = palette.text;
  ctx.font = '16px monospace';
  ctx.fillText(`Score ${state.score}`, 12, 24);
  ctx.fillText(`Best ${state.best}`, WIDTH - 110, 24);
  ctx.fillText(`Lives ${state.lives}`, WIDTH / 2 - 30, 24);
}

// --- Boot (browser entry point) --------------------------------------------

// Starts the game: wires up the canvas, the mouse and the animation loop.
// The only function that depends on the DOM; never called on import.
export function boot(doc = document) {
  const canvas = doc.getElementById('game');
  const ctx = canvas.getContext('2d');
  canvas.width = WIDTH;
  canvas.height = HEIGHT;

  const state = createState(1);
  state.best = loadBest(doc.defaultView?.localStorage ?? globalThis.localStorage);
  state.running = true;

  // Glow pass: a coarse offscreen light map, stretched over the field.
  const offscreen = doc.createElement('canvas');
  offscreen.width = GLOW_W;
  offscreen.height = GLOW_H;
  const glow = {
    map: createGlowMap(),
    image: offscreen.getContext('2d').createImageData(GLOW_W, GLOW_H),
  };

  // Move the paddle with the mouse.
  canvas.addEventListener('mousemove', (e) => {
    const rect = canvas.getBoundingClientRect();
    const x = e.clientX - rect.left - state.paddle.w / 2;
    state.paddle.x = Math.max(0, Math.min(WIDTH - state.paddle.w, x));
  });

  let last = performance.now();
  function loop(now) {
    const dt = Math.min((now - last) / 1000, 0.05);
    last = now;

    if (state.running) {
      const lost = step(state, dt);
      bounceBricks(state); // swept brick collision + scoring (pure logic)
      if (lost) {
        state.lives -= 1;
        state.combo = 0;
        if (state.lives <= 0) {
          state.best = saveBest(globalThis.localStorage, state.score);
          Object.assign(state, createState(state.level));
          state.best = loadBest(globalThis.localStorage);
        } else {
          // relaunch the ball
          state.ball = createState(state.level).ball;
        }
      }

      // Level cleared: all bricks broken
      if (state.bricks.every((b) => !b.alive)) {
        state.level += 1;
        state.bricks = makeBricks(state.level);
        state.ball = createState(state.level).ball;
      }
    }

    frame(ctx, state);
    drawGlow(ctx, glow, state, WIDTH, HEIGHT, offscreen);
    requestAnimationFrame(loop);
  }
  requestAnimationFrame(loop);

  return state;
}

// neon.test.js — PARTIAL coverage (on purpose).
//
// What is covered today: the collision primitive and a couple of physics
// bounces. What is NOT covered yet: score and combo (see ISSUES.md #5), nor
// level progression. This is a starting point for the testing work ahead, not
// a complete suite.
//
// Run: `node --test "game/**/*.test.js"`  (or `npm test`)

import { test } from 'node:test';
import assert from 'node:assert/strict';

import {
  collides,
  step,
  makeBricks,
  createState,
  bounceBricks,
  ballSpeed,
  BRICK_ROWS,
  BRICK_COLS,
  WIDTH,
} from './neon.js';

test('collides: clear overlap detected', () => {
  const ball = { x: 100, y: 100, r: 8 };
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), true);
});

test('collides: ball clearly away => no collision', () => {
  const ball = { x: 300, y: 300, r: 8 };
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), false);
});

test('collides: edge contact (radius) detected', () => {
  const ball = { x: 85, y: 100, r: 8 }; // right edge of the ball at 93 > 90
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), true);
});

test('step: bounce off the left wall', () => {
  const state = createState(1);
  state.ball = { x: 2, y: 200, r: 7, vx: -300, vy: 0 };
  step(state, 1 / 60);
  assert.ok(state.ball.vx > 0, 'horizontal velocity should flip to the right');
});

test('step: ball exiting through the bottom => lost', () => {
  const state = createState(1);
  state.ball = { x: 320, y: belowField(), r: 7, vx: 0, vy: 400 };
  const lost = step(state, 1 / 60);
  assert.equal(lost, true);
});

test('makeBricks: full, all-alive grid at start', () => {
  const bricks = makeBricks(1);
  assert.equal(bricks.length, BRICK_ROWS * BRICK_COLS);
  assert.ok(bricks.every((b) => b.alive));
  assert.ok(bricks.every((b) => b.x >= 0 && b.x + b.w <= WIDTH));
});

// Small local helper: place the ball below the field without importing the
// height (coverage intentionally light).
function belowField() {
  return 500;
}

// --- Brick bounce (D1-D5) --------------------------------------------------
// D1: the ball MUST be deflected when it hits a brick (today it plows through).
// Bricks carry no `col`; locate them by row and x. Col 3 -> x = 4 + 3*80 = 244,
// row 0 -> y = 48, row 2 -> y = 104 (see makeBricks).

const brickAt = (state, row, x) => state.bricks.find((b) => b.row === row && b.x === x);

test('D1: top-face hit bounces the ball up, kills the brick', () => {
  const state = createState(1);
  const brick = brickAt(state, 0, 244);
  state.ball = { px: 244, py: 35, x: 244, y: 45, r: 7, vx: 0, vy: 200 };
  bounceBricks(state);
  assert.equal(brick.alive, false);
  assert.ok(state.ball.vy < 0, `vy must point up after a top-face bounce, got ${state.ball.vy}`);
  assert.equal(state.ball.y, 41); // brick.y - BALL_R = 48 - 7
});

test('D2: after resolution the ball is outside the brick (no stick)', () => {
  const state = createState(1);
  const brick = brickAt(state, 0, 244);
  state.ball = { px: 244, py: 35, x: 244, y: 45, r: 7, vx: 0, vy: 200 };
  bounceBricks(state);
  assert.equal(collides(state.ball, brick), false);
});

test('D3: a step crossing two rows bounces off the FIRST brick only', () => {
  const state = createState(6); // level 6: speed 710, max step 35.5px
  const row0 = brickAt(state, 0, 244);
  const row1 = brickAt(state, 1, 244); // row 1 sits at y = 76
  state.ball = { px: 244, py: 40, x: 244, y: 75.5, r: 7, vx: 0, vy: 710 }; // 35.5 = 710 * 0.05
  bounceBricks(state);
  assert.equal(row0.alive, false);
  assert.equal(row1.alive, true, 'the second row must survive the same pass');
  assert.ok(state.ball.vy < 0);
});

test('D4: a level-6 head-on step that jumps a whole brick is still caught (swept)', () => {
  const state = createState(6);
  const brick = brickAt(state, 0, 244);
  state.ball = { px: 244, py: 40, x: 244, y: 75.5, r: 7, vx: 0, vy: 710 };
  // The discrete end-position test sees no overlap at all: the ball ended up
  // fully BELOW the brick (top edge 68.5 > 68). Only a sweep catches it.
  assert.equal(collides(state.ball, brick), false);
  bounceBricks(state);
  assert.equal(brick.alive, false);
  assert.ok(state.ball.vy < 0);
  assert.equal(state.ball.y, 41); // pushed back out through the top face
});

test('D5a: side hit flips vx only', () => {
  // Single-brick state: the inflated boxes of neighbouring columns overlap
  // (6px), so a ball approaching a face from the side would legitimately hit
  // the neighbour first. Isolate the face resolution.
  const state = createState(1);
  state.bricks = [{ x: 244, y: 104, w: 72, h: 20, row: 2, alive: true, points: 30 }];
  const brick = state.bricks[0];
  state.ball = { px: 230, py: 110, x: 240, y: 115, r: 7, vx: 10, vy: 300 };
  bounceBricks(state);
  assert.equal(brick.alive, false);
  assert.ok(state.ball.vx < 0, `vx must flip left, got ${state.ball.vx}`);
  assert.equal(state.ball.vy, 300, 'vy is untouched by a side hit');
  assert.equal(state.ball.x, 237); // brick.x - BALL_R = 244 - 7
});

test('D5b: an exact corner hit flips both velocities', () => {
  const state = createState(1);
  state.bricks = [{ x: 244, y: 104, w: 72, h: 20, row: 2, alive: true, points: 30 }];
  const brick = state.bricks[0];
  state.ball = { px: 230, py: 90, x: 240, y: 100, r: 7, vx: 100, vy: 100 };
  bounceBricks(state);
  assert.equal(brick.alive, false);
  assert.ok(state.ball.vx < 0 && state.ball.vy < 0, 'corner hit must flip both axes');
});

// --- Paddle (D6-D7) --------------------------------------------------------
// The paddle band is 12px tall (PADDLE_H) at y = 448. A step longer than 12px
// used to jump straight over it (level 1 at dt = 0.05: 260 * 0.05 = 13px).

test('D6a: paddle band-skip at dt=0.05 still bounces', () => {
  const state = createState(1);
  state.ball = { px: 320, py: 440.5, x: 320, y: 453.5, r: 7, vx: 0, vy: 260 };
  step(state, 0.05); // bottom edge jumps 447.5 -> 460.5, over the whole band
  assert.ok(state.ball.vy < 0, `ball must bounce off the paddle, got vy=${state.ball.vy}`);
  assert.equal(state.ball.y, 441); // paddle.y - BALL_R = 448 - 7
});

test('D6b: ball deep inside the paddle (teleported under it) still bounces', () => {
  const state = createState(1);
  state.ball = { px: 320, py: 455, x: 320, y: 455, r: 7, vx: 0, vy: 260 };
  step(state, 1 / 60);
  assert.ok(state.ball.vy < 0);
  assert.equal(state.ball.y, 441);
});

test('D7: paddle bounce renormalizes the speed to ballSpeed(level)', () => {
  const state = createState(1);
  state.ball = { px: 320, py: 436, x: 320, y: 441, r: 7, vx: 0, vy: 300 };
  step(state, 1 / 60);
  const v = Math.hypot(state.ball.vx, state.ball.vy);
  assert.equal(v, ballSpeed(1));
});



